.wf-shop-field .iti__selected-country{border-radius:8px 0 0 8px;font:inherit;color:var(--shop-text);min-height:44px}
.wf-shop-field .iti__selected-country:focus-visible{outline:2px solid var(--shop-accent);outline-offset:3px}
