.wf-shop:has([data-wf-shared-commerce-account]){width:100%;max-width:560px;padding:clamp(24px,5vw,48px) max(20px,env(safe-area-inset-left)) 56px}
[data-wf-shared-commerce-account]{width:100%;min-width:0}
.wf-shop-shell a{position:relative;min-width:44px;min-height:44px;justify-content:center}
.wf-shop-shell [data-wf-cart-link] svg{width:24px;height:24px}
