.wf-orders__list,.wf-orders__items{display:grid;gap:12px;margin:20px 0}
.wf-orders__row,.wf-orders__items article{display:grid;gap:8px;text-align:left;width:100%;padding:18px;border:1px solid var(--shop-border);border-radius:12px;background:var(--shop-surface);color:var(--shop-text);font:inherit;overflow-wrap:anywhere}
.wf-orders__row{cursor:pointer;grid-template-columns:minmax(0,1fr) auto}.wf-orders__row span:first-of-type{grid-column:1;font-size:.9rem;color:var(--shop-muted)}.wf-orders__row span:last-child{grid-column:2;grid-row:1/3;align-self:center;font-weight:700}
