.wf-shop-address>.wf-shop-help{grid-column:1/-1;margin:0}.wf-shop-new-address{justify-self:start;min-height:44px;padding:8px 12px;border:1px solid var(--shop-border);border-radius:8px;text-decoration:none}
.wf-shop-step-panel{align-content:start}.wf-shop-step-panel>[hidden]{display:none}.wf-shop-step-actions{padding-top:6px}
.wf-shop-line>a:not(:has(img)),.wf-shop-line>span{min-width:0;overflow-wrap:anywhere}.wf-shop-line>a:not(:has(img)){flex:1}.wf-shop-line>img{flex:none}.wf-shop-line>.wf-shop-link{flex:none;min-height:44px}
@media(max-width:700px){.wf-shop-step-panel{gap:16px}.wf-shop-step-actions{flex-wrap:wrap}.wf-shop-step-actions>.wf-shop-btn{min-height:48px}.wf-shop-new-address{width:100%}.wf-shop-line__controls{padding-left:0;gap:10px}.wf-shop-line__controls .wf-shop-link{min-height:44px}.wf-shop-line__controls strong{min-width:0}.wf-shop-loading__row{height:110px}}
@media(prefers-reduced-motion:reduce){.wf-shop-loading__row{animation:none}}

scripts.content:
(function (global) {
  'use strict';
  var labels = { firstName: 'Ime', lastName: 'Prezime', email: 'Email adresa', phone: 'Telefon',
    companyName: 'Naziv firme', taxNumber: 'PIB / OIB', address: 'Adresa', postalCode: 'Poštanski broj',
    city: 'Mesto', registrationNumber: 'Matični broj', companyEmail: 'Email firme', companyPhone: 'Telefon firme' };
  function node(tag, attrs, children) {
    var e = document.createElement(tag);
    Object.keys(attrs || {}).forEach(function (key) {
      if (key === 'text') e.textContent = attrs[key];
      else if (key === 'className') e.className = attrs[key];
      else if (attrs[key] !== false && attrs[key] != null) e.setAttribute(key, attrs[key] === true ? '' : attrs[key]);
    });
    (children || []).forEach(function (child) { e.appendChild(child); }); return e;
  }
  function randomKey() {
    return Array.from(global.crypto.getRandomValues(new Uint8Array(32))).map(function (n) { return n.toString(16).padStart(2, '0'); }).join('');
  }
  function post(url, data, signal) {
    return fetch(url, { method: 'POST', credentials: 'same-origin', signal: signal, headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, body: JSON.stringify(data) })
      .then(function (response) { return response.json().catch(function () { return { ok: false, message: 'Registracija trenutno nije dostupna.' }; }).then(function (result) {
        if (!response.ok || !result.ok) { var error = new Error(result.message || 'Zahtev trenutno nije dostupan.'); error.status = response.status; throw error; } return result;
      }); });
  }
  var phoneLoader;
  function loadPhone() {
    if (global.intlTelInput && global.intlTelInput.utils) return Promise.resolve(global.intlTelInput);
    if (phoneLoader) return phoneLoader;
    phoneLoader = new Promise(function (resolve, reject) {
      var script = node('script', { src: '/common/intl-tel-input/dist/js/intlTelInputWithUtils.min.js?v=29.1.2' });
      var timer = global.setTimeout(failed, 15000);
      function failed() { global.clearTimeout(timer); script.remove(); phoneLoader = null; reject(new Error('Provera telefona trenutno nije dostupna. Pokušajte ponovo.')); }
      if (!document.getElementById('elastyc-intl-tel-css')) document.head.appendChild(node('link', {
        id: 'elastyc-intl-tel-css', rel: 'stylesheet', href: '/common/intl-tel-input/dist/css/intlTelInput.min.css?v=29.1.2'
      }));
      script.onload = function () {
        if (!global.intlTelInput || !global.intlTelInput.utils) { failed(); return; }
        global.clearTimeout(timer); resolve(global.intlTelInput);
      };
      script.onerror = failed; document.head.appendChild(script);
    });
    return phoneLoader;
  }
  function phoneControl(input, country, notify) {
    var active = true, widget = null, observer = null, unavailable = false;
    function fit() {
      if (!active || !widget) return;
      var button = input.parentNode.querySelector('.iti__selected-country');
      if (button) input.style.setProperty('padding-left', (button.offsetWidth + 10) + 'px', 'important');
      var list = input.parentNode.querySelector('.iti__country-selector');
      if (list && input.offsetWidth) list.style.width = input.offsetWidth + 'px';
    }
    function validate() {
      input.setCustomValidity('');
      if (!input.value.trim()) return '';
      if (!widget) return unavailable ? 'Provera telefona trenutno nije dostupna. Ponovo otvorite registraciju.' : 'Sačekajte učitavanje provere telefona.';
      var utils = global.intlTelInput.utils, value = widget.getNumber();
      return value && utils.isValidNumberPrecise(value, null, null) && !utils.getExtension(value, null) ? '' : 'Unesite ispravan broj telefona za izabranu državu.';
    }
    loadPhone().then(function (factory) {
      if (!active) return;
      widget = factory(input, {
        initialCountry: country.toLowerCase(), countryOrder: [country.toLowerCase(), 'rs', 'ba', 'hr', 'me', 'si', 'mk'],
        countrySelectorMode: 'DROPDOWN', countryNameLocale: 'sr-Latn', allowedNumberTypes: null,
        allowNumberExtensions: false, allowPhonewords: false, numberDisplayFormat: 'NATIONAL',
        placeholderNumberPolicy: 'OFF', separateDialCode: true, strictMode: true,
        uiTranslations: { searchPlaceholder: 'Pretraga zemlje', selectedCountryAriaLabel: 'Izaberite zemlju za telefonski broj',
          noCountrySelected: 'Zemlja nije izabrana', countryListAriaLabel: 'Zemlje', clearSearchAriaLabel: 'Očisti pretragu', searchEmptyState: 'Nema rezultata' }
      });
      widget.setDisabled(input.disabled); fit();
      if (global.ResizeObserver) { observer = new global.ResizeObserver(fit); observer.observe(input); }
    }).catch(function (error) { if (active) { unavailable = true; notify(error.message); } });
    input.addEventListener('input', function () { input.setCustomValidity(''); });
    input.addEventListener('blur', function () { input.setCustomValidity(validate()); });
    input.addEventListener('countrychange', function () { input.setCustomValidity(''); fit(); });
    return {
      value: function () { var message = validate(); input.setCustomValidity(message); if (message) throw new Error(message); return input.value.trim() ? widget.getNumber() : ''; },
      setCountry: function (iso) { country = iso; if (widget && !input.value.trim()) { widget.setCountry(iso.toLowerCase()); fit(); } },
      setDisabled: function (value) { if (widget) widget.setDisabled(value); },
      destroy: function () { if (!active) return; active = false; if (observer) observer.disconnect(); if (widget) widget.destroy(); }
    };
  }
  function mount(options) {
    var host = options.host; host.replaceChildren();
    var alive = true, sequence = 0, controls = [], fields = {}, key = randomKey(), registryValues = {};
    var phone = null;
    var lookupTimer = null, lookupDeadline = null, lookupController = null, lookupKey = '';
    function cancelLookup() {
      sequence++; global.clearTimeout(lookupTimer); global.clearTimeout(lookupDeadline); lookupTimer = null; lookupDeadline = null;
      if (lookupController) lookupController.abort(); lookupController = null;
    }
    function destroy() { if (!alive) return; alive = false; cancelLookup(); if (phone) phone.destroy(); host.replaceChildren(); }
    var title = node('h2', { className: 'efa-title', text: options.token ? 'Potvrdite email i postavite lozinku' : 'Registracija' });
    var status = node('p', { className: 'efa-lead', role: 'status', 'aria-live': 'polite', text: options.token
      ? 'Posle potvrde emaila registraciju pregleda operater.' : 'Pošaljite podatke, potvrdite email i sačekajte odobravanje registracije. Obavezna polja su označena zvezdicom.' });
    var error = node('p', { className: 'efa-error', role: 'alert', hidden: true });
    var form = node('form', { className: 'efa-form' });
    var loading = node('p', { className: 'efa-loading', role: 'status', 'aria-live': 'polite', hidden: true, text: 'Slanje podataka…' });
    var base = '/incKomponente/auth/';
    host.append(title, status, error, form, loading);
    function busy(value) { host.setAttribute('aria-busy', String(value)); loading.hidden = !value; controls.forEach(function (c) { c.disabled = value; }); if (phone) phone.setDisabled(value); }
    function fail(e) { if (!alive) return; error.hidden = false; error.textContent = e.message || 'Zahtev trenutno nije dostupan.'; busy(false); }
    function clearError() { error.hidden = true; error.textContent = ''; }
    function input(name, label, required, type, max, container) {
      var control = node('input', { type: type || 'text', name: name, required: required, maxlength: max || 255,
        autocomplete: name === 'email' ? 'email' : name === 'firstName' ? 'given-name' : name === 'lastName' ? 'family-name' : name.indexOf('password') === 0 ? 'new-password' : 'on' });
      var wrap = node(name === 'phone' ? 'div' : 'label', { className: 'efa-field' }, [node('span', { text: label + (required ? ' *' : '') }), control]);
      (container || form).appendChild(wrap); fields[name] = control; controls.push(control); return wrap;
    }
    var submit = node('button', { className: 'efa-primary', type: 'submit', text: options.token ? 'Potvrdi email' : 'Pošalji registraciju' });
    controls.push(submit);
    var back = node('button', { type: 'button', className: 'efa-link', text: 'Nazad na prijavu' });
    back.addEventListener('click', function () { destroy(); options.onBack(); }); controls.push(back);
    if (options.token) {
      input('password', 'Lozinka — najmanje 12 znakova', true, 'password', 128).querySelector('input').minLength = 12;
      input('passwordConfirmation', 'Ponovite lozinku', true, 'password', 128);
      form.appendChild(submit); host.appendChild(back);
      form.addEventListener('submit', function (event) {
        event.preventDefault(); error.hidden = true;
        if (fields.password.value !== fields.passwordConfirmation.value) { fail(new Error('Lozinke se ne podudaraju.')); return; }
        busy(true);
        post(base + 'register-confirm.php', { token: options.token, password: fields.password.value }).then(function (result) {
          if (!alive) return; if (phone) { phone.destroy(); phone = null; } form.remove(); status.textContent = result.message; busy(false); controls = [back];
        }).catch(fail);
      });
      return { destroy: destroy };
    }
    var config = options.config, type = node('select', { name: 'type', 'aria-label': 'Vrsta kupca' }), country = node('select', { name: 'country' });
    config.types.forEach(function (value) { type.appendChild(node('option', { value: value, text: value === 'PL' ? 'Pravno lice' : 'Fizičko lice' })); });
    config.countries.forEach(function (value) { country.appendChild(node('option', { value: value.id, text: value.name })); });
    if (config.countries.some(function (value) { return value.id === config.defaultCountry; })) country.value = config.defaultCountry;
    form.appendChild(node('label', { className: 'efa-field' }, [node('span', { text: 'Vrsta kupca' }), type]));
    controls.push(type, country);
    var names = node('div', { className: 'efa-name-row' }); form.appendChild(names);
    ['firstName','lastName'].forEach(function (name) { input(name, labels[name], true, 'text', 30, names); });
    input('email', labels.email, true, 'email', 100);
    fields.email.inputMode = 'email'; fields.email.autocapitalize = 'none'; fields.email.spellcheck = false;
    function emailValidity() {
      fields.email.value = fields.email.value.trim(); fields.email.setCustomValidity('');
      if (fields.email.value && (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(fields.email.value) || fields.email.validity && fields.email.validity.typeMismatch)) {
        fields.email.setCustomValidity('Unesite važeću email adresu, na primer ime@firma.rs.');
      }
    }
    fields.email.addEventListener('input', function () { fields.email.setCustomValidity(''); });
    fields.email.addEventListener('blur', emailValidity);
    input('phone', labels.phone, false, 'tel', 100); fields.phone.autocomplete = 'tel-national';
    phone = phoneControl(fields.phone, country.value, function (message) { fail(new Error(message)); update(); });
    var countryCaption = node('span'), countryValue = config.countries.length === 1
      ? node('span', { text: config.countries[0].name }) : country;
    form.appendChild(node(config.countries.length === 1 ? 'div' : 'label', { className: 'efa-field' }, [countryCaption, countryValue]));
    var company = node('fieldset', { className: 'efa-registration-company' }, [node('legend', { text: 'Podaci firme' })]); form.appendChild(company);
    input('taxNumber', 'PIB', true, 'text', 20, company);
    var lookup = node('button', { className: 'efa-link', type: 'button', text: 'Pokušaj ponovo', hidden: true }); controls.push(lookup); company.appendChild(lookup);
    var registryState = node('p', { className: 'efa-lead', role: 'status', 'aria-live': 'polite' }); company.appendChild(registryState);
